// Trend series for the code register (domain/trend.ts).
//
// Three populations of test live here and it matters which is which:
//
//   FIXTURE PARITY — test/fixtures/trend.json is a BYTE COPY from gas/, generated by the
//   Python domain layer (gas/test/export_*.py). It is never edited or regenerated here. It
//   is fed through a RENAME SHIM (below) that maps gas/'s scan-log shape onto this
//   register's, and NOTHING ELSE: every base row, every option and every expected value
//   goes in verbatim.
//
//   PORTED HAND CASES — gas/test/trend.test.ts's own hand-computed blocks, carried across
//   with their arithmetic comments intact. Three adaptations, each stated at the site:
//     * scans carry no `shape` — the column does not exist here (see `pointTimes`), so the
//       "ignores non-flat scans" assertions are replaced by their opposite: a scan is
//       counted whatever stray `shape` it carries.
//     * the group dimension is `repo_name` read through `groupKeyOf("repo")`, not gas/'s
//       host-only `asset` — insights.GROUP_COLUMNS is the only dimension list.
//     * `withCoverageEfficiency`'s block comes from gas/test/program.test.ts (it tests
//        trend.ts through program.ts) and its rows carry `scope: "sca"`, because
//        program.classifyRisk resolves the rule per scope.
//
//   NEW — the scope filter (rule 2 of the D8 brief), the per-scope stack, the secrets
//   refusal, and the backfill/scope interaction. Every number is derived with the
//   arithmetic written out.

import { describe, expect, it } from "vitest";
import { DEFAULT_RISK_RULE, SCOPES, type RiskRule } from "../src/domain/config";
import { GROUP_COLUMNS } from "../src/domain/insights";
import { RISK_TIER_ORDER } from "../src/domain/program";
import {
  awaitingFixAsOf,
  cohortSlaAttainment,
  groupKeyOf,
  kmMedianAsOf,
  kmMedianByGroupTrend,
  kmSkipMask,
  medianMttrByGroupTrend,
  openByGroupTrend,
  openByRiskTierTrend,
  openBySeverityTrend,
  perScopeSeries,
  trendByScope,
  trendFromBase,
  trendFromFrames,
  withCoverageEfficiency,
  withKmMedian,
  withOpenPastSla,
  withSlaBurn,
} from "../src/domain/trend";
import type { Rec } from "../src/domain/util";
import { expectParity, fixture } from "./helpers";

// --------------------------------------------------------------------------- #
//  trend.json rename shim
// --------------------------------------------------------------------------- #

/**
 * gas/ column -> gas_devsecops column, for the columns THIS module reads.
 *
 * It is empty, and that is the finding rather than an oversight: trend.ts reads `severity`,
 * `first_seen`, `resolved_at`, `mttr_days`, `fix_available_at` and `actionable_from`, and not
 * one of them is renamed in this register. The renames ledgerTypes.ts's header lists
 * (vuln_key -> finding_key, cve -> identifier, asset_* -> repo_*, cloud -> platform) all land
 * on columns the trend never touches. The mapping is declared anyway so the accounting test
 * below is a real check and not a tautology.
 */
const RENAMED: Record<string, string> = {};

/** THE FIXTURE FIELDS WITH NO COUNTERPART, listed rather than silently dropped. */
const UNMAPPED: Record<string, string> = {
  // ledgerTypes.ScanRow has no `shape`: gas/'s flat-vs-grouped split describes a fetch that
  // aggregates findings per asset, and every scope's fetch here is a flat per-finding scan.
  // The fixture's one `grouped` scan exists ONLY to exercise the filter this port removes
  // (see trend.pointTimes's DIVERGENCE note), so the shim drops that row rather than
  // inventing a column for it — and the assertion below makes the drop visible.
  shape: "no shape column on this register's scans tab; every scope's fetch is a flat scan",
};

/** Everything else passes through under its own name. */
const PASSTHROUGH = ["scan_id", "ts", "severity", "first_seen", "resolved_at", "mttr_days"];

/** Added by the shim: `scope` is part of every row's identity here and gas/ has no such column. */
const ADDED = ["scope"];

const RAW = fixture("trend");

function shimScans(scans: any[]): Rec[] {
  return scans
    .filter((s) => s.shape === "flat")
    .map(({ shape: _shape, ...rest }) => ({ ...rest, scope: "sca" }));
}

function shimBase(base: any[]): Rec[] {
  return base.map((r) => ({ ...r, scope: "sca" }));
}

const FX_SCANS = shimScans(RAW.scans);
const FX_BASE = shimBase(RAW.base);

describe("trend.json rename shim — the mapping itself", () => {
  const seenFields = new Set<string>();
  for (const s of RAW.scans) for (const k of Object.keys(s)) seenFields.add(k);
  for (const r of RAW.base) for (const k of Object.keys(r)) seenFields.add(k);

  it("every field the fixture carries is either renamed, passed through, or listed as unmapped", () => {
    const accounted = new Set([
      ...Object.keys(RENAMED),
      ...Object.keys(UNMAPPED),
      ...PASSTHROUGH,
    ]);
    const unaccounted = [...seenFields].filter((f) => !accounted.has(f)).sort();
    expect(unaccounted, "fixture fields with no shim entry").toEqual([]);
    // 7 fields: 0 renamed + 1 unmapped + 6 passed through. Nothing this module reads is renamed.
    expect(seenFields.size).toBe(7);
    expect(Object.keys(RENAMED).length + Object.keys(UNMAPPED).length + PASSTHROUGH.length)
      .toBe(7);
  });

  it("the shim drops exactly the one grouped scan, and stamps every row with a scope", () => {
    expect(RAW.scans.length).toBe(4);
    expect(FX_SCANS.length).toBe(3); // s1, s2, s3 — `sg` is the grouped one
    expect(RAW.scans.filter((s: any) => s.shape !== "flat").map((s: any) => s.scan_id))
      .toEqual(["sg"]);
    expect(FX_SCANS.every((s) => s["scope"] === "sca" && !("shape" in s))).toBe(true);
    expect(FX_BASE.every((r) => r["scope"] === "sca")).toBe(true);
    expect(ADDED).toEqual(["scope"]);
  });
});

describe("trendFromFrames (fixture parity)", () => {
  it("matches the unscoped Python trend", () => {
    expectParity(trendFromFrames(FX_SCANS, FX_BASE), RAW.expected.all);
  });
  it("matches the CRITICAL+HIGH scoped trend", () => {
    expectParity(
      trendFromFrames(FX_SCANS, FX_BASE, ["CRITICAL", "HIGH"]),
      RAW.expected.scoped_critical_high,
    );
  });
  it("returns [] for empty inputs", () => {
    expectParity(trendFromFrames([], FX_BASE), []);
    expectParity(trendFromFrames(FX_SCANS, []), []);
  });
  it("the fixture is all-sca, so scope:'sca' is the same series and scope:'sast' is empty", () => {
    expectParity(trendFromFrames(FX_SCANS, FX_BASE, null, { scope: "sca" }), RAW.expected.all);
    expect(trendFromFrames(FX_SCANS, FX_BASE, null, { scope: "sast" })).toEqual([]);
  });
});

// --------------------------------------------------------------------------- #
//  ported hand cases
