describe("awaitingFixAsOf", () => {
  // Millisecond scalars keep the arithmetic legible: open as of d iff first<=d and not
  // resolved by d; awaiting iff also no fix available by d (fixAvail null or > d).
  it("open with no fix ever -> awaiting", () => {
    expect(awaitingFixAsOf(5, null, null, 10)).toBe(true);
  });
  it("open with a fix available by d -> not awaiting", () => {
    expect(awaitingFixAsOf(5, null, 8, 10)).toBe(false);
  });
  it("open with a fix that only lands after d -> awaiting (re-enters later)", () => {
    expect(awaitingFixAsOf(5, null, 20, 10)).toBe(true);
  });
  it("resolved by d -> not open as of d -> not awaiting", () => {
    expect(awaitingFixAsOf(5, 8, null, 10)).toBe(false);
  });
  it("not yet detected as of d -> not open -> not awaiting", () => {
    expect(awaitingFixAsOf(15, null, null, 10)).toBe(false);
  });
  it("open now, resolves after d, no fix -> still awaiting as of d", () => {
    expect(awaitingFixAsOf(5, 20, null, 10)).toBe(true);
  });
});

describe("no shape gate (DIVERGENCE from gas/)", () => {
  // gas/ samples only at scans with `shape === "flat"`. This register's scans tab has no
  // `shape` column at all, so the branch is gone: EVERY scan in the log is a sample point.
  // The inverted assertion is deliberate — a port that silently kept the filter would read
  // every trend empty (no writer sets the column), which looks exactly like an empty
  // register, and "a zero has to prove it looked".
  const base = [
    { severity: "HIGH", first_seen: "2025-12-31T00:00:00Z", resolved_at: null, mttr_days: null },
  ];

  it("counts a scan carrying a stray non-flat shape value", () => {
    const out = trendFromFrames([{ ts: "2026-01-01T00:00:00Z", shape: "grouped" }], base);
    expect(out.map((p) => p.date)).toEqual(["2026-01-01T00:00:00Z"]);
    expect(out[0].open).toBe(1);
  });

  it("counts a scan with no shape column at all — the real row shape here", () => {
    expect(trendFromFrames([{ ts: "2026-01-01T00:00:00Z" }], base).map((p) => p.open)).toEqual([1]);
  });

  it("the whole group family agrees — none of them gate on shape either", () => {
    const scans = [{ ts: "2026-01-01T00:00:00Z", shape: "grouped" }];
    const groupBase = [{ ...base[0], repo_name: "web" }];
    const keyOf = groupKeyOf("repo");
    expect(openBySeverityTrend(scans, base).length).toBe(1);
    expect(openByGroupTrend(scans, groupBase, keyOf, ["web"]).length).toBe(1);
    expect(medianMttrByGroupTrend(scans, groupBase, keyOf, ["web"]).length).toBe(1);
    expect(kmMedianByGroupTrend(scans, groupBase, keyOf, ["web"]).length).toBe(1);
    expect(trendFromBase(scans, base).length).toBe(1);
  });
});

describe("trendFromFrames hideNoFix (as-of-date open exclusion)", () => {
  // Three findings first seen 2026-07-03:
  //   R1 open, no fix ever;  R2 open, fix available 07-10;  R3 resolved 07-08, fix 07-04.
  // Points d1 = 07-05, d2 = 07-15.
  const scans = [{ ts: "2026-07-05T00:00:00Z" }, { ts: "2026-07-15T00:00:00Z" }];
  const base = [
    { severity: "HIGH", first_seen: "2026-07-03T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: null },
    { severity: "HIGH", first_seen: "2026-07-03T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: "2026-07-10T00:00:00Z" },
    { severity: "HIGH", first_seen: "2026-07-03T00:00:00Z", resolved_at: "2026-07-08T00:00:00Z", mttr_days: 5, fix_available_at: "2026-07-04T00:00:00Z" },
  ];

  it("hideNoFix:true steps the open count down, R2 re-entering once its fix lands", () => {
    const out = trendFromFrames(scans, base, null, { hideNoFix: true });
    // d1: R1 hidden (no fix), R2 hidden (fix 07-10 > 07-05), R3 open + fix-by-d1 -> shown. open 1.
    // d2: R1 hidden, R2 re-enters (fix 07-10 <= 07-15), R3 resolved. open 1.
    expect(out.map((p) => p.open)).toEqual([1, 1]);
    // Resolved series is independent of hideNoFix: none by d1, R3 by d2.
    expect(out.map((p) => p.resolved)).toEqual([0, 1]);
  });

  it("hideNoFix absent / false is byte-identical to today (parity lock)", () => {
    const today = trendFromFrames(scans, base);
    expect(trendFromFrames(scans, base, null, {})).toEqual(today);
    expect(trendFromFrames(scans, base, null, { hideNoFix: false })).toEqual(today);
    // With the toggle off (today), all three are open at d1 and R1+R2 at d2.
    expect(today.map((p) => p.open)).toEqual([3, 2]);
    expect(today.map((p) => p.resolved)).toEqual([0, 1]);
    // The resolved-derived series match between hideNoFix on and off.
    const hidden = trendFromFrames(scans, base, null, { hideNoFix: true });
    expect(hidden.map((p) => p.median_days)).toEqual(today.map((p) => p.median_days));
    expect(hidden.map((p) => p.sla_pct)).toEqual(today.map((p) => p.sla_pct));
  });
});

describe("openBySeverityTrend", () => {
  // Two scans a day apart. A CRITICAL first seen before scan 1 and resolved between the two
  // must read open at scan 1, resolved (absent) at scan 2. A HIGH first seen before both and
  // never resolved stays open at both. A LOW first seen only after scan 1 appears at scan 2.
  const scans = [{ ts: "2026-01-01T00:00:00Z" }, { ts: "2026-01-02T00:00:00Z" }];
  const base = [
    { severity: "CRITICAL", first_seen: "2025-12-31T00:00:00Z", resolved_at: "2026-01-01T12:00:00Z" },
    { severity: "HIGH", first_seen: "2025-12-30T00:00:00Z", resolved_at: null },
    { severity: "LOW", first_seen: "2026-01-01T06:00:00Z", resolved_at: null },
  ];

  it("counts open per severity as of each scan", () => {
    expect(openBySeverityTrend(scans, base)).toEqual([
      { date: "2026-01-01T00:00:00Z", bySev: { CRITICAL: 1, HIGH: 1 } },
      { date: "2026-01-02T00:00:00Z", bySev: { HIGH: 1, LOW: 1 } },
    ]);
  });

  it("restricts to the requested severities (+ UNKNOWN)", () => {
    expect(openBySeverityTrend(scans, base, ["HIGH"])).toEqual([
      { date: "2026-01-01T00:00:00Z", bySev: { HIGH: 1 } },
      { date: "2026-01-02T00:00:00Z", bySev: { HIGH: 1 } },
    ]);
  });

  it("returns [] for empty inputs", () => {
    expect(openBySeverityTrend([], base)).toEqual([]);
    expect(openBySeverityTrend(scans, [])).toEqual([]);
  });

  it("hideNoFix excludes awaiting-as-of-date findings; a fixed-later severity re-enters", () => {
    const nfScans = [{ ts: "2026-07-05T00:00:00Z" }, { ts: "2026-07-15T00:00:00Z" }];
    const nfBase = [
      { severity: "HIGH", first_seen: "2026-07-03T00:00:00Z", resolved_at: null, fix_available_at: null }, // awaiting -> hidden both
      { severity: "CRITICAL", first_seen: "2026-07-03T00:00:00Z", resolved_at: null, fix_available_at: "2026-07-10T00:00:00Z" }, // fix 07-10: hidden at d1, shown at d2
      { severity: "LOW", first_seen: "2026-07-03T00:00:00Z", resolved_at: null, fix_available_at: "2026-07-01T00:00:00Z" }, // fix before: shown both
    ];
    expect(openBySeverityTrend(nfScans, nfBase, null, { hideNoFix: true })).toEqual([
      { date: "2026-07-05T00:00:00Z", bySev: { LOW: 1 } },
      { date: "2026-07-15T00:00:00Z", bySev: { CRITICAL: 1, LOW: 1 } },
    ]);
    // Parity: absent/false is byte-identical, with all three open at both dates.
    const today = openBySeverityTrend(nfScans, nfBase);
    expect(openBySeverityTrend(nfScans, nfBase, null, { hideNoFix: false })).toEqual(today);
    expect(today).toEqual([
      { date: "2026-07-05T00:00:00Z", bySev: { HIGH: 1, CRITICAL: 1, LOW: 1 } },
      { date: "2026-07-15T00:00:00Z", bySev: { HIGH: 1, CRITICAL: 1, LOW: 1 } },
    ]);
  });
});

describe("groupKeyOf / GROUP_COLUMNS", () => {
  // The dimension list is insights.GROUP_COLUMNS, imported rather than restated so the trend
  // and the breakdown tree can never name a different set (D8 brief rule 1).
  it("is exactly the register's five dimensions", () => {
    expect(Object.keys(GROUP_COLUMNS).sort())
      .toEqual(["cwe", "language", "owner_project", "repo", "secret_kind"]);
  });

  it("reads each dimension's own ledger column", () => {
    const row = {
      repo_name: "svc-api", language: "python", owner_project: "platform",
      secret_kind: "PASSWORD", cwe: "CWE-79",
    };
    expect(groupKeyOf("repo")(row)).toBe("svc-api");
    expect(groupKeyOf("language")(row)).toBe("python");
    expect(groupKeyOf("owner_project")(row)).toBe("platform");
    expect(groupKeyOf("secret_kind")(row)).toBe("PASSWORD");
    expect(groupKeyOf("cwe")(row)).toBe("CWE-79");
  });

  it("refuses an unknown dimension rather than silently reading a missing column", () => {
    // A missing column would read "" -> "(none)" for every row, which looks like a register
    // where nobody set the field. Refusing names the mistake instead.
    expect(() => groupKeyOf("cloud")).toThrow(/unknown group dimension/);
  });
});

describe("openByGroupTrend", () => {
  // Two scans a day apart. The group dimension is `repo` (insights.GROUP_COLUMNS.repo ->
  // repo_name); groups ["web", "db"] each keep their own series, everything else -> "Other".
  const scans = [{ ts: "2026-01-01T00:00:00Z" }, { ts: "2026-01-02T00:00:00Z" }];
  const keyOf = groupKeyOf("repo");
  const groups = ["web", "db"];
  const open = (repo_name: unknown, over: Rec = {}) => ({
    repo_name, severity: "HIGH", first_seen: "2025-12-31T00:00:00Z", resolved_at: null, ...over,
  });

  it("returns [] with no scans or no base rows", () => {
    expect(openByGroupTrend([], [open("web")], keyOf, groups)).toEqual([]);
    expect(openByGroupTrend(scans, [], keyOf, groups)).toEqual([]);
  });

  it("counts open per group as of a single scan", () => {
    const base = [open("web"), open("web"), open("db")];
    expect(openByGroupTrend([scans[0]], base, keyOf, groups)).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: 2, db: 1 } },
    ]);
  });

  it("drops a row from its group at the scan after it resolves", () => {
    const base = [open("web", { resolved_at: "2026-01-01T12:00:00Z" }), open("db")];
    expect(openByGroupTrend(scans, base, keyOf, groups)).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: 1, db: 1 } },
      { date: "2026-01-02T00:00:00Z", byGroup: { db: 1 } },
    ]);
  });

  it("normalizes null / blank group values to (none)", () => {
    const base = [open(null), open(""), open("web")];
    // "(none)" only keeps its own series when it's one of the requested groups.
    expect(openByGroupTrend([scans[0]], base, keyOf, ["(none)", "web"])).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { "(none)": 2, web: 1 } },
    ]);
  });

  it("folds values outside groups into Other; includeOther:false drops them", () => {
    const base = [open("web"), open("cache"), open("queue")];
    expect(openByGroupTrend([scans[0]], base, keyOf, groups)).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: 1, Other: 2 } },
    ]);
    expect(openByGroupTrend([scans[0]], base, keyOf, groups, { includeOther: false })).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: 1 } },
    ]);
  });

  it("honors a custom otherLabel", () => {
    expect(
      openByGroupTrend([scans[0]], [open("cache")], keyOf, groups, { otherLabel: "Rest" }),
    ).toEqual([{ date: "2026-01-01T00:00:00Z", byGroup: { Rest: 1 } }]);
  });

  it("scopes to the chosen severities plus UNKNOWN", () => {
    const base = [
      open("web", { severity: "CRITICAL" }),
      open("web", { severity: "HIGH" }),   // filtered out when scoped to CRITICAL
      open("db", { severity: "UNKNOWN" }), // UNKNOWN is never hidden
    ];
    expect(openByGroupTrend([scans[0]], base, keyOf, groups, { severities: ["CRITICAL"] })).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: 1, db: 1 } },
    ]);
  });

  it("groups by any GROUP_COLUMNS dimension, not just repo", () => {
    const base = [
      open("web", { secret_kind: "PASSWORD" }),
      open("web", { secret_kind: "PASSWORD" }),
      open("db", { secret_kind: "SAAS_API_KEY" }),
    ];
    expect(
      openByGroupTrend([scans[0]], base, groupKeyOf("secret_kind"), ["PASSWORD", "SAAS_API_KEY"]),
    ).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { PASSWORD: 2, SAAS_API_KEY: 1 } },
    ]);
  });
});

describe("medianMttrByGroupTrend", () => {
  // Two scans a day apart, grouped by repo. `res` mints a resolved row with a fixed mttr
  // sample; resolved_at null (+ mttr null) is an open row.
  const scans = [{ ts: "2026-01-01T00:00:00Z" }, { ts: "2026-01-02T00:00:00Z" }];
  const keyOf = groupKeyOf("repo");
  const groups = ["web", "db"];
  const res = (
    repo_name: unknown,
    mttr: number | null,
    resolved_at: string | null,
    over: Rec = {},
  ) => ({
    repo_name, severity: "HIGH", first_seen: "2025-12-31T00:00:00Z", resolved_at,
    mttr_days: mttr, ...over,
  });

  it("computes the exact median per group per ts (odd + even counts, 3-dp rounding)", () => {
    const base = [
      res("web", 2, "2026-01-01T00:00:00Z"),
      res("web", 9, "2026-01-01T00:00:00Z"),
      res("web", 4, "2026-01-01T00:00:00Z"),     // odd -> middle sample 4
      res("db", 1, "2026-01-01T00:00:00Z"),
      res("db", 1.3334, "2026-01-01T00:00:00Z"), // even -> (1 + 1.3334)/2 = 1.1667 -> 1.167
    ];
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups)).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 4, db: 1.167 } },
    ]);
  });

  it("emits null before a group's first resolution, then a number once one resolves <= ts", () => {
    // web resolves at noon on Jan 1 (after scan 1, before scan 2); db never resolves.
    const base = [res("web", 3, "2026-01-01T12:00:00Z")];
    expect(medianMttrByGroupTrend(scans, base, keyOf, groups)).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: null, db: null } },
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 3, db: null } },
    ]);
  });

  it("excludes rows resolved after ts, includes them (and the <= boundary) once resolved", () => {
    const base = [
      res("web", 5, "2026-01-01T00:00:00Z"),  // resolved exactly at scan 1 -> included (<=)
      res("web", 7, "2026-01-01T18:00:00Z"),  // resolved after scan 1 -> in only at scan 2
    ];
    expect(medianMttrByGroupTrend(scans, base, keyOf, groups)).toEqual([
      { date: "2026-01-01T00:00:00Z", byGroup: { web: 5, db: null } }, // just [5]
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 6, db: null } }, // median [5,7]
    ]);
  });

  it("never pools open rows or resolved rows without an mttr sample", () => {
    const base = [
      res("web", 4, "2026-01-01T00:00:00Z"),
      res("web", null, null),                   // still open -> skipped
      res("db", null, "2026-01-01T00:00:00Z"),  // resolved but mttr null -> skipped
    ];
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups)).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 4, db: null } },
    ]);
  });

  it("scopes to the chosen severities plus UNKNOWN", () => {
    const base = [
      res("web", 2, "2026-01-01T00:00:00Z", { severity: "CRITICAL" }),
      res("web", 10, "2026-01-01T00:00:00Z", { severity: "HIGH" }),   // filtered out
      res("db", 6, "2026-01-01T00:00:00Z", { severity: "UNKNOWN" }),  // never hidden
    ];
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups, { severities: ["CRITICAL"] })).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 2, db: 6 } },
    ]);
  });

  it("pools Other's median over the remainder (not a sum); includeOther:false drops; custom otherLabel", () => {
    const base = [
      res("web", 4, "2026-01-01T00:00:00Z"),
      res("cache", 2, "2026-01-01T00:00:00Z"),
      res("queue", 8, "2026-01-01T00:00:00Z"),
    ];
    // cache + queue fold to Other -> median([2, 8]) = 5, never the sum 10.
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups)).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 4, db: null, Other: 5 } },
    ]);
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups, { includeOther: false })).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 4, db: null } },
    ]);
    expect(
      medianMttrByGroupTrend(
        [scans[1]],
        [res("cache", 2, "2026-01-01T00:00:00Z"), res("queue", 8, "2026-01-01T00:00:00Z")],
        keyOf,
        groups,
        { otherLabel: "Rest" },
      ),
    ).toEqual([{ date: "2026-01-02T00:00:00Z", byGroup: { web: null, db: null, Rest: 5 } }]);
  });

  it("normalizes null / blank group values to (none)", () => {
    const base = [
      res(null, 3, "2026-01-01T00:00:00Z"),
      res("", 5, "2026-01-01T00:00:00Z"),
      res("web", 9, "2026-01-01T00:00:00Z"),
    ];
    // "(none)" only keeps its own series when requested; median([3,5]) = 4.
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, ["(none)", "web"])).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { "(none)": 4, web: 9 } },
    ]);
  });

  it("returns [] for empty inputs", () => {
    expect(medianMttrByGroupTrend([], [res("web", 3, "2026-01-01T00:00:00Z")], keyOf, groups)).toEqual([]);
    expect(medianMttrByGroupTrend(scans, [], keyOf, groups)).toEqual([]);
  });

  it("minMttrDays drops fast-lane samples (mttr <= threshold), strictly", () => {
    const base = [
      res("web", 0.5, "2026-01-01T00:00:00Z"), // fast lane — dropped
      res("web", 1, "2026-01-01T00:00:00Z"),   // exactly at threshold — dropped (strict >)
      res("web", 6, "2026-01-01T00:00:00Z"),
      res("web", 10, "2026-01-01T00:00:00Z"),  // tail median = (6+10)/2 = 8
      res("db", 0.2, "2026-01-01T00:00:00Z"),  // db has only fast-lane resolutions -> null
    ];
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups, { minMttrDays: 1 })).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: 8, db: null } },
    ]);
  });

  it("minMttrDays applies to the pooled Other remainder too", () => {
    const base = [
      res("cache", 0.5, "2026-01-01T00:00:00Z"), // dropped from the pool
      res("cache", 4, "2026-01-01T00:00:00Z"),
      res("queue", 12, "2026-01-01T00:00:00Z"),  // Other tail median = (4+12)/2 = 8
    ];
    expect(medianMttrByGroupTrend([scans[1]], base, keyOf, groups, { minMttrDays: 1 })).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: null, db: null, Other: 8 } },
    ]);
  });
});

describe("kmMedianByGroupTrend", () => {
  // Same repo-keyed groups as medianMttrByGroupTrend, but rows carry first_seen (for the
  // censored risk set) and open rows are real (resolved_at: null, mttr_days: null) instead of
  // being skipped — a KM curve needs its censored ages, not just its events.
  const keyOf = groupKeyOf("repo");
  const groups = ["web", "db"];
  const res = (
    repo_name: unknown,
    mttr: number | null,
    resolved_at: string | null,
    over: Rec = {},
  ) => ({
    repo_name, severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at,
    mttr_days: mttr, ...over,
  });

  it("per-group KM median, with censoring pulling it above the naive (closed-only) median", () => {
    // web: two events (2, 4) plus two still-open rows, all first seen Jan 1. As of Jan 10
    // (age 9 for the open pair): events [2,4], risk set [2,4,9,9].
    //   t=2: atRisk 4, d 1 -> S=.75.  t=4: atRisk 3, d 1 -> S=.75*(2/3)=.5 <= .5 -> median 4.
    const base = [
      res("web", 2, "2026-01-03T00:00:00Z"),
      res("web", 4, "2026-01-05T00:00:00Z"),
      res("web", null, null),
      res("web", null, null),
    ];
    const scan = { ts: "2026-01-10T00:00:00Z" };
    expect(kmMedianByGroupTrend([scan], base, keyOf, groups)).toEqual([
      { date: "2026-01-10T00:00:00Z", byGroup: { web: 4, db: null } },
    ]);
    // Naive median (closed-only [2,4]) is 3 — lower than KM's 4, proving the two open rows'
    // censoring is doing real work rather than KM silently matching the naive figure.
    expect(medianMttrByGroupTrend([scan], base, keyOf, groups)).toEqual([
      { date: "2026-01-10T00:00:00Z", byGroup: { web: 3, db: null } },
    ]);
  });

  it("emits null before any event and before the 0.5 crossing, then a number once crossed", () => {
    // Four web findings first seen Jan 1, resolved 2/4/6/8 days later.
    const base = [
      res("web", 2, "2026-01-03T00:00:00Z"),
      res("web", 4, "2026-01-05T00:00:00Z"),
      res("web", 6, "2026-01-07T00:00:00Z"),
      res("web", 8, "2026-01-09T00:00:00Z"),
    ];
    const scans = [
      { ts: "2026-01-02T00:00:00Z" }, // nothing resolved yet -> no curve -> null
      { ts: "2026-01-04T00:00:00Z" }, // event [2], 3 censored at age 3: S=.75 -> null
      { ts: "2026-01-10T00:00:00Z" }, // events [2,4,6,8]: t2 S=.75, t4 S=.5 -> median 4
    ];
    expect(kmMedianByGroupTrend(scans, base, keyOf, groups)).toEqual([
      { date: "2026-01-02T00:00:00Z", byGroup: { web: null, db: null } },
      { date: "2026-01-04T00:00:00Z", byGroup: { web: null, db: null } },
      { date: "2026-01-10T00:00:00Z", byGroup: { web: 4, db: null } },
    ]);
  });

  it("pools Other's KM median over the remainder (not per-repo); includeOther:false drops", () => {
    // cache + queue both fold into Other and share ONE risk set — proving Other's curve is
    // pooled, not computed per source repo. cache has an event (3) plus a still-open row
    // (censored at age 9); queue has an event (7).
    //   events [3,7], risk set [3,7,9]: t=3 atRisk 3 d1 -> S=.667; t=7 atRisk 2 d1 ->
    //   S=.667*.5=.333 <= .5 -> median 7.
    const base = [
      res("cache", 3, "2026-01-04T00:00:00Z"),
      res("cache", null, null),
      res("queue", 7, "2026-01-08T00:00:00Z"),
    ];
    const scan = { ts: "2026-01-10T00:00:00Z" };
    expect(kmMedianByGroupTrend([scan], base, keyOf, groups)).toEqual([
      { date: "2026-01-10T00:00:00Z", byGroup: { web: null, db: null, Other: 7 } },
    ]);
    expect(kmMedianByGroupTrend([scan], base, keyOf, groups, { includeOther: false })).toEqual([
      { date: "2026-01-10T00:00:00Z", byGroup: { web: null, db: null } },
    ]);
  });

  it("scopes to the chosen severities plus UNKNOWN", () => {
    const base = [
      res("web", 2, "2026-01-03T00:00:00Z", { severity: "CRITICAL" }),
      res("web", 10, "2026-01-01T00:00:00Z", { severity: "HIGH" }), // filtered out
      res("db", 6, "2026-01-05T00:00:00Z", { severity: "UNKNOWN" }), // never hidden
    ];
    const scan = { ts: "2026-01-10T00:00:00Z" };
    // web scoped to CRITICAL: only event [2] -> atRisk 1, d1 -> S=0 <= .5 -> median 2.
    // db (UNKNOWN, always kept): only event [6] -> median 6.
    expect(kmMedianByGroupTrend([scan], base, keyOf, groups, { severities: ["CRITICAL"] })).toEqual([
      { date: "2026-01-10T00:00:00Z", byGroup: { web: 2, db: 6 } },
    ]);
  });

  it("hideNoFix drops awaiting-as-of-ts rows from the censored risk set (median can appear)", () => {
    // One resolved event (mttr 2, fix available) plus three awaiting-vendor-fix open rows
    // (fix_available_at null).
    const base = [
      res("web", 2, "2026-01-03T00:00:00Z", { fix_available_at: "2026-01-01T00:00:00Z" }),
      res("web", null, null, { fix_available_at: null }),
      res("web", null, null, { fix_available_at: null }),
      res("web", null, null, { fix_available_at: null }),
    ];
    const scan = { ts: "2026-01-10T00:00:00Z" };
    // Default: the three awaiting rows stay censored at age 9 -> risk set [2,9,9,9] ->
    // t=2 atRisk 4 d1 -> S=.75 -> null.
    expect(kmMedianByGroupTrend([scan], base, keyOf, groups)[0].byGroup.web).toBeNull();
    // hideNoFix: those three leave the risk set entirely -> risk set [2] -> S=0 -> median 2.
    expect(kmMedianByGroupTrend([scan], base, keyOf, groups, { hideNoFix: true })[0].byGroup.web).toBe(2);
  });

  it("returns [] for empty inputs", () => {
    const base = [res("web", 3, "2026-01-05T00:00:00Z")];
    expect(kmMedianByGroupTrend([], base, keyOf, groups)).toEqual([]);
    expect(kmMedianByGroupTrend([{ ts: "2026-01-10T00:00:00Z" }], [], keyOf, groups)).toEqual([]);
  });
});

describe("trendFromBase (backfill)", () => {
  // One real scan on Jul 6. Two findings first seen in June (Jun 6, Jun 20); one critical is
  // API-resolved Jul 6 with a 2-day span. Backfill should reconstruct a daily backbone from
  // Jun 6 up to (excluding) Jul 6, tagged reconstructed, with exact cumulative open counts.
  const scans = [{ ts: "2026-07-06T10:00:00Z" }];
  const base = [
    { severity: "HIGH", first_seen: "2026-06-06T00:00:00Z", resolved_at: null, mttr_days: null },
    { severity: "MEDIUM", first_seen: "2026-06-20T00:00:00Z", resolved_at: null, mttr_days: null },
    {
      severity: "CRITICAL", first_seen: "2026-07-04T00:00:00Z",
      resolved_at: "2026-07-06T00:00:00Z", mttr_days: 2,
    },
  ];

  it("with backfill off is exactly trendFromFrames, all reconstructed:false", () => {
    const out = trendFromBase(scans, base);
    expect(out.length).toBe(1);
    expect(out[0].date).toBe("2026-07-06T10:00:00Z");
    expect(out[0].reconstructed).toBe(false);
    const { reconstructed: _r, ...bare } = out[0];
    expect([bare]).toEqual(trendFromFrames(scans, base));
  });

  it("reconstructs a daily backbone from the earliest first_seen to the first scan", () => {
    const out = trendFromBase(scans, base, null, { backfill: true });
    // 30 synthetic days (Jun 6 .. Jul 5 inclusive) + 1 real scan.
    expect(out[0].date).toBe("2026-06-06T00:00:00Z");
    expect(out.filter((p) => p.reconstructed).length).toBe(30);
    expect(out.filter((p) => !p.reconstructed).length).toBe(1);
    expect(out[out.length - 1].date).toBe("2026-07-06T10:00:00Z");
    expect(out[out.length - 1].reconstructed).toBe(false);
    // Open counts are the exact cumulative first_seen<=ts population.
    expect(out.find((p) => p.date === "2026-06-06T00:00:00Z")!.open).toBe(1);
    expect(out.find((p) => p.date === "2026-06-20T00:00:00Z")!.open).toBe(2);
  });

  it("does not backfill when the earliest first_seen is not before the first scan", () => {
    const laterBase = base.map((r) => ({ ...r, first_seen: "2026-07-06T00:00:00Z" }));
    const out = trendFromBase(scans, laterBase, null, { backfill: true });
    expect(out.length).toBe(1);
    expect(out.every((p) => !p.reconstructed)).toBe(true);
  });

  it("returns [] for empty inputs even with backfill on", () => {
    expect(trendFromBase([], base, null, { backfill: true })).toEqual([]);
    expect(trendFromBase(scans, [], null, { backfill: true })).toEqual([]);
  });

  it("stamps synthetic scans with the requested scope, so the backbone survives the filter", () => {
    // NEW (rule 2). trendFromFrames filters the SCAN LOG by scope as well as the rows, so a
    // synthetic backbone row without a `scope` would be dropped one line after it is built and
    // the backfill would silently vanish — the register reading as if it had no history.
    const scopedScans = [{ ts: "2026-07-06T10:00:00Z", scope: "sca" }];
    const scopedBase = base.map((r) => ({ ...r, scope: "sca" }));
    const out = trendFromBase(scopedScans, scopedBase, null, { backfill: true, scope: "sca" });
    expect(out.filter((p) => p.reconstructed).length).toBe(30);
    // And it is exactly the unscoped answer on an all-sca state.
    expect(out).toEqual(trendFromBase(scans, base, null, { backfill: true }));
  });
});

describe("withOpenPastSla", () => {
  // A CRITICAL (target 7) open all along, a HIGH resolved Jan 10, and an UNKNOWN (no target)
  // open all along, all first seen Jan 1.
  const base = [
    { severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
    { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-10T00:00:00Z" },
    { severity: "UNKNOWN", first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
  ];

  it("counts open-past-SLA as of each point date and preserves existing fields", () => {
    // Jan 5: CRITICAL age 4d <= 7 -> none breached. Jan 15: CRITICAL age 14d > 7 -> 1
    // (HIGH is resolved by then; UNKNOWN has no target).
    const points = [
      { date: "2026-01-05T00:00:00Z", open: 99, foo: "a" },
      { date: "2026-01-15T00:00:00Z", open: 88, foo: "b" },
    ];
    expect(withOpenPastSla(points, base)).toEqual([
      { date: "2026-01-05T00:00:00Z", open: 99, foo: "a", open_past_sla: 0 },
      { date: "2026-01-15T00:00:00Z", open: 88, foo: "b", open_past_sla: 1 },
    ]);
  });

  it("scopes to the chosen severities plus UNKNOWN", () => {
    const b = [
      { severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", resolved_at: null }, // 14d > 7 -> breached
      { severity: "MEDIUM", first_seen: "2025-11-01T00:00:00Z", resolved_at: null }, // ~75d > 30 -> breached
      { severity: "UNKNOWN", first_seen: "2026-01-01T00:00:00Z", resolved_at: null }, // no target
    ];
    const points = [{ date: "2026-01-15T00:00:00Z" }];
    // Unscoped: CRITICAL + MEDIUM breach = 2.
    expect(withOpenPastSla(points, b)[0].open_past_sla).toBe(2);
    // Scoped to CRITICAL: MEDIUM filtered out, UNKNOWN kept (but never breaches) -> 1.
    expect(withOpenPastSla(points, b, ["CRITICAL"])[0].open_past_sla).toBe(1);
  });

  it("a finding resolved before the point date drops out", () => {
    const b = [{ severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-10T00:00:00Z" }];
    // Jan 9: still open (resolved_at > d), age 8d > 7 -> breached.
    expect(withOpenPastSla([{ date: "2026-01-09T00:00:00Z" }], b)[0].open_past_sla).toBe(1);
    // Jan 20: resolved by then -> not open -> 0.
    expect(withOpenPastSla([{ date: "2026-01-20T00:00:00Z" }], b)[0].open_past_sla).toBe(0);
  });

  it("counts synthetic/reconstructed points the same as real ones (by date only)", () => {
    const b = [{ severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", resolved_at: null }];
    const points = [
      { date: "2026-01-15T00:00:00Z", reconstructed: true }, // synthetic backfill day
      { date: "2026-01-15T00:00:00Z", reconstructed: false }, // real saved scan, same date
    ];
    const out = withOpenPastSla(points, b);
    expect(out[0].open_past_sla).toBe(1);
    expect(out[1].open_past_sla).toBe(out[0].open_past_sla);
    // Passthrough keeps the reconstructed flag untouched.
    expect(out.map((p) => p.reconstructed)).toEqual([true, false]);
  });

  it("fromField 'actionable_from' shifts breach ages and skips null-actionable rows", () => {
    // All CRITICAL (target 7). A has a fix from detection; B's fix arrived on Jan 10; C is
    // awaiting a vendor fix (null actionable_from). As of Jan 15:
    //   default (first_seen origin): all three age 14d > 7 -> 3 breached.
    //   actionable_from origin: A ages from Jan 1 (14d, breached); B ages from Jan 10 (5d,
    //   within target); C is skipped (null origin) -> 1 breached.
    const b = [
      { severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null },
      { severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", actionable_from: "2026-01-10T00:00:00Z", resolved_at: null },
      { severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", actionable_from: null, resolved_at: null },
    ];
    const points = [{ date: "2026-01-15T00:00:00Z" }];
    expect(withOpenPastSla(points, b)[0].open_past_sla).toBe(3);
    expect(withOpenPastSla(points, b, null, "actionable_from")[0].open_past_sla).toBe(1);
  });
});

describe("withSlaBurn", () => {
  // All CRITICAL (target 7), actionable_from Jan 1 -> deadline Jan 8. Scans Jan 1 / Jan 10 /
  // Jan 20 bracket the deadline (crossing in window 2) and B's late resolution (window 3).
  //   A: never resolved -> crosses into breach.
  //   B: resolved Jan 15, AFTER the deadline -> crosses, then clears.
  //   C: resolved Jan 5, BEFORE the deadline -> never breaches, never counts.
  //   D: awaiting a vendor fix (null actionable_from) -> never counts.
  //   E: UNKNOWN, no SLA target -> never counts.
  const base = [
    { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null },
    { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-15T00:00:00Z" },
    { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z" },
    { severity: "CRITICAL", actionable_from: null, resolved_at: null },
    { severity: "UNKNOWN", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null },
  ];
  const points = [
    { date: "2026-01-01T00:00:00Z", foo: "a" },
    { date: "2026-01-10T00:00:00Z", foo: "b" },
    { date: "2026-01-20T00:00:00Z", foo: "c" },
  ];

  it("first point is null; entered/cleared/net per window; exclusions never count", () => {
    expect(withSlaBurn(points, base)).toEqual([
      { date: "2026-01-01T00:00:00Z", foo: "a", sla_entered: null, sla_cleared: null, sla_net: null },
      // Window (Jan 1, Jan 10]: A and B cross into breach (deadline Jan 8, unresolved by it);
      // C resolved before its deadline; D/E excluded. entered 2, cleared 0.
      { date: "2026-01-10T00:00:00Z", foo: "b", sla_entered: 2, sla_cleared: 0, sla_net: 2 },
      // Window (Jan 10, Jan 20]: no new deadlines; B's late resolution (Jan 15 > deadline)
      // clears. entered 0, cleared 1.
      { date: "2026-01-20T00:00:00Z", foo: "c", sla_entered: 0, sla_cleared: 1, sla_net: -1 },
    ]);
  });

  it("scopes to the chosen severities plus UNKNOWN", () => {
    const b = [
      { severity: "HIGH", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null }, // deadline Jan 15
      { severity: "MEDIUM", actionable_from: "2025-12-01T00:00:00Z", resolved_at: null }, // deadline ~Dec 31
    ];
    const pts = [{ date: "2026-01-01T00:00:00Z" }, { date: "2026-01-20T00:00:00Z" }];
    // Unscoped window (Jan 1, Jan 20]: HIGH deadline Jan 15 in window; MEDIUM deadline Dec 31
    // is before Jan 1, so it does not cross this window -> only HIGH enters.
    expect(withSlaBurn(pts, b)[1].sla_entered).toBe(1);
    // Scoped to HIGH: MEDIUM filtered out entirely -> still 1.
    expect(withSlaBurn(pts, b, ["HIGH"])[1].sla_entered).toBe(1);
    // A window that brackets the MEDIUM deadline shows it unscoped but not when scoped to HIGH.
    const ptsDec = [{ date: "2025-12-01T00:00:00Z" }, { date: "2026-01-20T00:00:00Z" }];
    expect(withSlaBurn(ptsDec, b)[1].sla_entered).toBe(2);
    expect(withSlaBurn(ptsDec, b, ["HIGH"])[1].sla_entered).toBe(1);
  });
});

describe("cohortSlaAttainment", () => {
  // All CRITICAL (target 7), actionable_from Jan 1 -> deadline Jan 8.
  //   A: still open -> misses (open past deadline).
  //   B: resolved Jan 15, after the deadline -> misses (late).
  //   C: resolved Jan 5, on time -> hits.
  const base = [
    { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null },
    { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-15T00:00:00Z" },
    { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z" },
  ];

  it("cohort membership by deadline<=d; late/open miss, on-time hits; empty cohort null", () => {
    const points = [
      { date: "2026-01-05T00:00:00Z", foo: "a" }, // deadline Jan 8 not yet passed -> empty cohort
      { date: "2026-01-10T00:00:00Z", foo: "b" }, // all three in cohort; 1 of 3 on time -> 33.3
    ];
    expect(cohortSlaAttainment(points, base)).toEqual([
      { date: "2026-01-05T00:00:00Z", foo: "a", sla_attainment_pct: null },
      { date: "2026-01-10T00:00:00Z", foo: "b", sla_attainment_pct: 33.3 },
    ]);
  });

  it("excludes awaiting-vendor-fix and no-target rows from the cohort", () => {
    const b = [
      { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z" }, // on time
      { severity: "CRITICAL", actionable_from: null, resolved_at: null }, // awaiting -> excluded
      { severity: "UNKNOWN", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null }, // no target -> excluded
    ];
    // Only the one CRITICAL is in the cohort as of Jan 10, and it was on time -> 100.
    expect(cohortSlaAttainment([{ date: "2026-01-10T00:00:00Z" }], b)[0].sla_attainment_pct).toBe(100);
  });

  it("resolved exactly at the deadline counts as on time (<=)", () => {
    const b = [{ severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-08T00:00:00Z" }];
    // deadline is Jan 1 + 7d = Jan 8; resolved exactly then -> met.
    expect(cohortSlaAttainment([{ date: "2026-01-10T00:00:00Z" }], b)[0].sla_attainment_pct).toBe(100);
  });

  it("rounds attainment to one decimal place", () => {
    // 2 of 3 on time = 66.666… -> 66.7.
    const b = [
      { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z" },
      { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: "2026-01-06T00:00:00Z" },
      { severity: "CRITICAL", actionable_from: "2026-01-01T00:00:00Z", resolved_at: null },
    ];
    expect(cohortSlaAttainment([{ date: "2026-01-10T00:00:00Z" }], b)[0].sla_attainment_pct).toBe(66.7);
  });
});

describe("withKmMedian", () => {
  // Four HIGH findings all first seen 2026-01-01, resolved 2/4/6/8 days later. As of an early
  // date only some have resolved (the rest are right-censored at their current age); as of a
  // late date all four are events and the KM staircase crosses 0.5.
  const base = [
    { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-03T00:00:00Z", mttr_days: 2 },
    { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z", mttr_days: 4 },
    { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-07T00:00:00Z", mttr_days: 6 },
    { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-09T00:00:00Z", mttr_days: 8 },
  ];

  it("null before any event / before the 0.5 crossing; KM median as of each date", () => {
    const points = [
      { date: "2026-01-02T00:00:00Z", foo: "a" }, // nothing resolved yet -> null
      { date: "2026-01-04T00:00:00Z", foo: "b" }, // event [2], three censored at age 3: t2 n=4 S=.75 -> null
      { date: "2026-01-10T00:00:00Z", foo: "c" }, // events [2,4,6,8]: t2 S=.75, t4 S=.5 -> median 4
    ];
    expect(withKmMedian(points, base)).toEqual([
      { date: "2026-01-02T00:00:00Z", foo: "a", km_median_days: null },
      { date: "2026-01-04T00:00:00Z", foo: "b", km_median_days: null },
      { date: "2026-01-10T00:00:00Z", foo: "c", km_median_days: 4 },
    ]);
  });

  it("scopes to the chosen severities plus UNKNOWN", () => {
    const b = [
      { severity: "CRITICAL", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-03T00:00:00Z", mttr_days: 2 },
      { severity: "MEDIUM", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z", mttr_days: 4 },
      { severity: "UNKNOWN", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-07T00:00:00Z", mttr_days: 6 },
    ];
    const points = [{ date: "2026-01-10T00:00:00Z" }];
    // Unscoped events [2,4,6]: t2 n=3 S=.667, t4 n=2 S=.333 <= .5 -> median 4.
    // Scoped to CRITICAL (UNKNOWN kept) events [2,6]: t2 n=2 S=.5 <= .5 -> median 2.
    expect(withKmMedian(points, b)[0].km_median_days).toBe(4);
    expect(withKmMedian(points, b, ["CRITICAL"])[0].km_median_days).toBe(2);
  });

  it("rounds the KM median to 3 decimals like trendFromFrames", () => {
    // A single event at 5.0006: S drops straight to 0, so the median is that event time.
    const b = [{ severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-06T00:00:00Z", mttr_days: 5.0006 }];
    expect(withKmMedian([{ date: "2026-01-15T00:00:00Z" }], b)[0].km_median_days).toBe(5.001);
  });

  it("hideNoFix drops awaiting-as-of-date rows from the censored risk set (median can appear)", () => {
    // One resolved event at 2 (fix available), plus three awaiting-vendor-fix rows open as of
    // the point date (age 9, no fix ever). Censored, those three keep S above 0.5 -> no median;
    // hideNoFix removes them from the risk set, so the lone event crosses to 0 -> median 2.
    const b = [
      { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-03T00:00:00Z", mttr_days: 2, fix_available_at: "2026-01-01T00:00:00Z" },
      { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: null },
      { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: null },
      { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: null },
    ];
    const points = [{ date: "2026-01-10T00:00:00Z" }];
    // Default (toggle off): the three censored awaiting rows hold S at 0.75 -> null.
    expect(withKmMedian(points, b)[0].km_median_days).toBeNull();
    // Parity: absent vs explicit false are identical.
    expect(withKmMedian(points, b, null, { hideNoFix: false })).toEqual(withKmMedian(points, b));
    // hideNoFix: the awaiting rows leave the risk set; the resolved event still counts.
    expect(withKmMedian(points, b, null, { hideNoFix: true })[0].km_median_days).toBe(2);
  });

  describe("maxReconstructed sampling", () => {
    // A base whose events (as of a late date) give a stable KM median of 4, so every computed
    // point carries the same non-null value and only the compute/skip pattern varies.
    const late = base; // events [2,4,6,8] -> median 4 as of 2026-01-10+
    const mk = (n: number, reconstructed: boolean) =>
      Array.from({ length: n }, (_, i) => ({
        date: `2026-02-${String(i + 1).padStart(2, "0")}T00:00:00Z`,
        reconstructed,
      }));

    it("is byte-identical to unlimited when the backbone fits under the cap", () => {
      const points = mk(5, true);
      expect(withKmMedian(points, late, null, { maxReconstructed: 10 }))
        .toEqual(withKmMedian(points, late));
    });

    it("never skips real (non-reconstructed) points", () => {
      const points = mk(20, false);
      const out = withKmMedian(points, late, null, { maxReconstructed: 3 });
      expect(out.every((p) => p.km_median_days === 4)).toBe(true);
    });

    it("thins reconstructed points to an evenly spaced sample, keeping first + last", () => {
      const points = mk(20, true);
      const out = withKmMedian(points, late, null, { maxReconstructed: 5 });
      const computed = out.filter((p) => p.km_median_days !== null);
      expect(computed).toHaveLength(5);
      // Endpoints always retained.
      expect(out[0].km_median_days).toBe(4);
      expect(out[out.length - 1].km_median_days).toBe(4);
    });

    it("computes every real point and only samples the reconstructed backbone", () => {
      // 2 real points bracketing 10 reconstructed ones; cap the backbone at 4.
      const points = [
        { date: "2026-02-01T00:00:00Z", reconstructed: false },
        ...mk(10, true).map((p, i) => ({ ...p, date: `2026-02-${String(i + 2).padStart(2, "0")}T00:00:00Z` })),
        { date: "2026-02-20T00:00:00Z", reconstructed: false },
      ];
      const out = withKmMedian(points, late, null, { maxReconstructed: 4 });
      const realComputed = out.filter((p) => !p.reconstructed && p.km_median_days !== null);
      const reconComputed = out.filter((p) => p.reconstructed && p.km_median_days !== null);
      expect(realComputed).toHaveLength(2); // both real points always compute
      expect(reconComputed).toHaveLength(4); // backbone sampled to the cap
    });
  });

  describe("kmSkipMask", () => {
    it("returns null (skip nothing) when unset or the backbone fits", () => {
      const pts = [{ reconstructed: true }, { reconstructed: true }];
      expect(kmSkipMask(pts)).toBeNull();
      expect(kmSkipMask(pts, 5)).toBeNull();
    });

    it("skips only surplus reconstructed points, keeping evenly spaced endpoints", () => {
      const pts = [
        { reconstructed: false },
        { reconstructed: true }, { reconstructed: true }, { reconstructed: true },
        { reconstructed: true }, { reconstructed: true },
        { reconstructed: false },
      ];
      const mask = kmSkipMask(pts, 2)!;
      expect(mask[0]).toBe(false); // real point never skipped
      expect(mask[6]).toBe(false); // real point never skipped
      // Of the 5 reconstructed points (idx 1..5), exactly 2 kept (first + last of the run).
      const keptRecon = [1, 2, 3, 4, 5].filter((i) => !mask[i]);
      expect(keptRecon).toEqual([1, 5]);
    });

    it("the whole mask, index by index, at max 3 over 5 reconstructed points", () => {
      // NEW, and it is the perturbation guard: the ported test above reads only the kept SET,
      // so an off-by-one in `Math.round((k * last) / denom)` that still keeps the endpoints
      // slips through it. reconIdx = [1,2,3,4,5], last = 4, denom = 2:
      //   k=0 -> round(0)   = 0 -> keep idx 1
      //   k=1 -> round(4/2) = 2 -> keep idx 3
      //   k=2 -> round(8/2) = 4 -> keep idx 5
      const pts = [
        { reconstructed: false },
        { reconstructed: true }, { reconstructed: true }, { reconstructed: true },
        { reconstructed: true }, { reconstructed: true },
        { reconstructed: false },
      ];
      expect(kmSkipMask(pts, 3)).toEqual([false, false, true, false, true, false, false]);
    });

    it("max 0 skips every reconstructed point and max 1 keeps only the first", () => {
      const pts = [{ reconstructed: true }, { reconstructed: true }, { reconstructed: true }];
      expect(kmSkipMask(pts, 0)).toEqual([true, true, true]);
      // max 1: denom 1, k=0 -> round(0) = 0 -> the run's first index.
      expect(kmSkipMask(pts, 1)).toEqual([false, true, true]);
    });

    it("a negative cap means 'no cap', not 'skip everything'", () => {
      expect(kmSkipMask([{ reconstructed: true }], -1)).toBeNull();
    });
  });
});

describe("kmMedianAsOf", () => {
  // A mix of resolved (events) and still-open (censored) rows spanning several weeks.
  const base: Rec[] = [
    { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z", mttr_days: 4, fix_available_at: null },
    { severity: "HIGH", first_seen: "2026-01-02T00:00:00Z", resolved_at: "2026-01-12T00:00:00Z", mttr_days: 10, fix_available_at: null },
    { severity: "CRITICAL", first_seen: "2026-01-03T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: null },
    { severity: "LOW", first_seen: "2026-01-04T00:00:00Z", resolved_at: "2026-01-20T00:00:00Z", mttr_days: 16, fix_available_at: null },
  ];

  it("matches withKmMedian point-for-point across dates and severity scopes", () => {
    const dates = ["2026-01-06T00:00:00Z", "2026-01-13T00:00:00Z", "2026-01-21T00:00:00Z"];
    for (const severities of [null, ["HIGH"], ["CRITICAL", "HIGH"]] as (string[] | null)[]) {
      const series = withKmMedian(dates.map((date) => ({ date })), base, severities);
      dates.forEach((date, i) => {
        expect(kmMedianAsOf(base, severities, Date.parse(date))).toBe(series[i].km_median_days);
      });
    }
  });

  it("honors hideNoFix identically to withKmMedian (awaiting row drops from the risk set)", () => {
    const nfBase: Rec[] = [
      { severity: "HIGH", first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-01-05T00:00:00Z", mttr_days: 4, fix_available_at: "2026-01-02T00:00:00Z" },
      { severity: "HIGH", first_seen: "2026-01-02T00:00:00Z", resolved_at: null, mttr_days: null, fix_available_at: "2026-02-01T00:00:00Z" },
    ];
    const date = "2026-01-10T00:00:00Z";
    const [pt] = withKmMedian([{ date }], nfBase, null, { hideNoFix: true });
    expect(kmMedianAsOf(nfBase, null, Date.parse(date), { hideNoFix: true })).toBe(pt.km_median_days);
  });

  it("returns null for no rows or a null date", () => {
    expect(kmMedianAsOf([], null, Date.parse("2026-01-10T00:00:00Z"))).toBeNull();
    expect(kmMedianAsOf(base, null, null)).toBeNull();
  });
});

