//  withCoverageEfficiency — ported from gas/test/program.test.ts (it tests trend.ts)
// --------------------------------------------------------------------------- #

const RULE: RiskRule = DEFAULT_RISK_RULE; // KEV or exploit or EPSS >= 0.10

describe("withCoverageEfficiency (trend decorator)", () => {
  // Three high-risk lifecycles and one low-risk one, resolving on known dates, so the series
  // can be checked by hand at each point:
  //
  //   A  high, first seen 01-01, resolved 02-01
  //   B  high, first seen 01-01, still open
  //   C  high, first seen 03-01, resolved 03-15
  //   D  low,  first seen 01-01, resolved 02-01
  //   E  unknown signals, first seen 01-01, still open
  //
  //   as of 2026-01-15:  exists A,B,D,E. remediated none.
  //                      TP 0, FN 2 (A,B), FP 0  -> coverage 0%, efficiency null
  //   as of 2026-02-15:  A and D remediated.
  //                      TP 1, FN 1 (B), FP 1 (D) -> coverage 50%, efficiency 50%
  //   as of 2026-03-20:  C exists and is remediated too.
  //                      TP 2, FN 1 (B), FP 1 (D) -> coverage 66.7%, efficiency 66.7%
  //
  // ADAPTED: every row carries `scope: "sca"`. program.classifyRisk resolves the rule per
  // scope (`ruleForScope`), so a scope-less row would be refused — gas/ has one register and
  // needs no such column.
  const base = [
    { scope: "sca", severity: "HIGH", status: "RESOLVED", has_kev: true, has_exploit: false, epss: 0.01,
      first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-02-01T00:00:00Z" },
    { scope: "sca", severity: "HIGH", status: "OPEN", has_kev: true, has_exploit: false, epss: 0.01,
      first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
    { scope: "sca", severity: "HIGH", status: "RESOLVED", has_kev: true, has_exploit: false, epss: 0.01,
      first_seen: "2026-03-01T00:00:00Z", resolved_at: "2026-03-15T00:00:00Z" },
    { scope: "sca", severity: "HIGH", status: "RESOLVED", has_kev: false, has_exploit: false, epss: 0.01,
      first_seen: "2026-01-01T00:00:00Z", resolved_at: "2026-02-01T00:00:00Z" },
    { scope: "sca", severity: "HIGH", status: "OPEN", has_kev: null, has_exploit: null, epss: null,
      first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
  ];
  const points = [
    { date: "2026-01-15T00:00:00Z", open: 0 },
    { date: "2026-02-15T00:00:00Z", open: 0 },
    { date: "2026-03-20T00:00:00Z", open: 0 },
  ];
  const out = withCoverageEfficiency(points, base, RULE);

  it("computes both rates as of each point's date", () => {
    expect(out[0].coverage_pct).toBe(0);
    expect(out[0].efficiency_pct).toBeNull(); // nothing remediated yet
    expect(out[1].coverage_pct).toBe(50);
    expect(out[1].efficiency_pct).toBe(50);
    expect(out[2].coverage_pct).toBe(66.7);
    expect(out[2].efficiency_pct).toBe(66.7);
  });

  it("excludes rows that did not exist yet at the point's date", () => {
    // C is first seen 03-01, so it is absent from the first two points entirely.
    expect(out[0].high_risk_open).toBe(2); // A and B, not C
    expect(out[2].high_risk_remediated).toBe(2); // A and C
  });

  it("reports the unclassified share alongside the rates", () => {
    expect(out[0].unknown_pct).toBe(25); // E of the four rows that existed on 01-15
    expect(out[1].unknown_pct).toBe(25);
    expect(out[2].unknown_pct).toBe(20); // five rows exist by then
  });

  it("preserves the caller's existing point fields", () => {
    expect(out[0].date).toBe("2026-01-15T00:00:00Z");
    expect(out[0].open).toBe(0);
  });

  it("scopes to the given severities", () => {
    const scoped = withCoverageEfficiency(points, base, RULE, ["LOW"]);
    expect(scoped[2].coverage_pct).toBeNull(); // no HIGH rows left to score
  });

  it("omitting the rule falls back to each row's scope rule and gives the same answer", () => {
    // ruleForScope("sca") IS DEFAULT_RISK_RULE, so this must be identical, not merely close.
    expect(withCoverageEfficiency(points, base)).toEqual(out);
  });

  // ---- NEW: the secrets refusal -------------------------------------------------------
  it("excludes secrets rows and COUNTS them, rather than throwing or hiding them", () => {
    // program.classifyRisk THROWS on a secrets row (ruleForScope("secrets") is null): there is
    // no exploit intelligence for a hardcoded string. Two secrets rows are added to the same
    // base — one existing from 01-01, one only from 03-01.
    const mixed = [
      ...base,
      { scope: "secrets", severity: "LOW", status: "OPEN", has_kev: null, has_exploit: null, epss: null,
        first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
      { scope: "secrets", severity: "CRITICAL", status: "OPEN", has_kev: null, has_exploit: null, epss: null,
        first_seen: "2026-03-01T00:00:00Z", resolved_at: null },
    ];
    const mixedOut = withCoverageEfficiency(points, mixed, RULE);
    // Every rate is BYTE-IDENTICAL to the sca-only series: the secrets rows leave both sides.
    expect(mixedOut.map((p) => p.coverage_pct)).toEqual(out.map((p) => p.coverage_pct));
    expect(mixedOut.map((p) => p.efficiency_pct)).toEqual(out.map((p) => p.efficiency_pct));
    expect(mixedOut.map((p) => p.unknown_pct)).toEqual(out.map((p) => p.unknown_pct));
    // And the exclusion is REPORTED as of each date: 1 secret exists on 01-15 and 02-15, 2 by 03-20.
    expect(mixedOut.map((p) => p.secrets_excluded)).toEqual([1, 1, 2]);
    // The sca-only series excludes nothing.
    expect(out.map((p) => p.secrets_excluded)).toEqual([0, 0, 0]);
  });

  it("a secrets-only register yields null rates and the whole population as excluded", () => {
    const secretsOnly = [
      { scope: "secrets", severity: "LOW", status: "OPEN", has_kev: null, has_exploit: null, epss: null,
        first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
    ];
    const [p] = withCoverageEfficiency([points[2]], secretsOnly, RULE);
    expect(p.coverage_pct).toBeNull();
    expect(p.efficiency_pct).toBeNull();
    expect(p.unknown_pct).toBeNull(); // the classifiable population is empty, not 100% unknown
    expect(p.secrets_excluded).toBe(1);
  });
});

describe("openByRiskTierTrend", () => {
  // ADDITION over gas/, which has no risk-tier series. The tiers PARTITION the population
  // (program.RISK_TIER_ORDER), so `includeOther` is forced off and no row can fold away.
  const scans = [{ ts: "2026-02-15T00:00:00Z" }];
  const sca = (over: Rec) => ({
    scope: "sca", severity: "HIGH", status: "OPEN", has_kev: false, has_exploit: false, epss: 0.01,
    first_seen: "2026-01-01T00:00:00Z", resolved_at: null, ...over,
  });

  it("counts open findings per tier, and every tier is a RISK_TIER_ORDER name", () => {
    const base = [
      sca({ has_kev: true }),                       // kev
      sca({ has_exploit: true }),                   // exploit
      sca({ epss: 0.5 }),                           // epss
      sca({}),                                      // none (all observed, none fired)
      sca({ has_kev: null, has_exploit: null, epss: null }), // unknown
    ];
    const { points, secrets_excluded } = openByRiskTierTrend(scans, base, RULE);
    expect(points).toEqual([
      { date: "2026-02-15T00:00:00Z", byGroup: { kev: 1, exploit: 1, epss: 1, none: 1, unknown: 1 } },
    ]);
    expect(secrets_excluded).toBe(0);
    expect(Object.keys(points[0].byGroup).every((k) => (RISK_TIER_ORDER as string[]).includes(k)))
      .toBe(true);
  });

  it("drops secrets rows before classification and reports how many", () => {
    const base = [
      sca({ has_kev: true }),
      { scope: "secrets", severity: "LOW", status: "OPEN", first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
      { scope: "secrets", severity: "LOW", status: "OPEN", first_seen: "2026-01-01T00:00:00Z", resolved_at: null },
    ];
    const { points, secrets_excluded } = openByRiskTierTrend(scans, base, RULE);
    expect(points[0].byGroup).toEqual({ kev: 1 });
    expect(secrets_excluded).toBe(2);
  });
});

