describe("scope filter — rows AND the scan log", () => {
  // A mixed sca/secrets state. The two registers have DIFFERENT scan cadences on purpose: if
  // a function filtered only the rows and not the scan log, the sca series would still carry
  // the secrets scan dates and the assertion below would fail on point count alone.
  //
  //   sca scans:     Jan 1, Jan 5      secrets scans: Jan 3, Jan 7
  //   sca rows:      S1 CRITICAL first 2025-12-20, resolved 2026-01-04, mttr 15  (late)
  //                  S2 HIGH     first 2025-12-25, still open
  //   secrets rows:  X1 LOW      first 2025-09-01, still open                    (breached)
  //                  X2 CRITICAL first 2025-12-02, resolved 2025-12-05, mttr 3   (on time)
  //
  // The secrets rows' dates are chosen so the mixed answer DIFFERS from the sca-only one on
  // every series checked below — X1 is old enough to breach LOW's 90-day target, and X2 is
  // the only row in the whole state that meets its deadline. A first draft had X1 at
  // 2025-12-01 and X2 resolving 2026-01-06: both `open_past_sla` and `sla_attainment_pct`
  // then came out IDENTICAL scoped and unscoped, so the "genuinely differ" guard passed
  // vacuously and would not have caught a dropped filter.
  const scans: Rec[] = [
    { scan_id: "a1", ts: "2026-01-01T00:00:00Z", scope: "sca" },
    { scan_id: "b1", ts: "2026-01-03T00:00:00Z", scope: "secrets" },
    { scan_id: "a2", ts: "2026-01-05T00:00:00Z", scope: "sca" },
    { scan_id: "b2", ts: "2026-01-07T00:00:00Z", scope: "secrets" },
  ];
  const base: Rec[] = [
    { scope: "sca", repo_name: "web", severity: "CRITICAL", status: "RESOLVED",
      has_kev: true, has_exploit: false, epss: 0.01,
      first_seen: "2025-12-20T00:00:00Z", resolved_at: "2026-01-04T00:00:00Z", mttr_days: 15,
      actionable_from: "2025-12-20T00:00:00Z", fix_available_at: "2025-12-20T00:00:00Z" },
    { scope: "sca", repo_name: "web", severity: "HIGH", status: "OPEN",
      has_kev: false, has_exploit: false, epss: 0.01,
      first_seen: "2025-12-25T00:00:00Z", resolved_at: null, mttr_days: null,
      actionable_from: "2025-12-25T00:00:00Z", fix_available_at: "2025-12-25T00:00:00Z" },
    { scope: "secrets", repo_name: "db", severity: "LOW", status: "OPEN",
      first_seen: "2025-09-01T00:00:00Z", resolved_at: null, mttr_days: null,
      actionable_from: "2025-09-01T00:00:00Z", fix_available_at: "2025-09-01T00:00:00Z" },
    { scope: "secrets", repo_name: "db", severity: "CRITICAL", status: "RESOLVED",
      first_seen: "2025-12-02T00:00:00Z", resolved_at: "2025-12-05T00:00:00Z", mttr_days: 3,
      actionable_from: "2025-12-02T00:00:00Z", fix_available_at: "2025-12-02T00:00:00Z" },
  ];
  const scaScans = scans.filter((s) => s["scope"] === "sca");
  const scaBase = base.filter((r) => r["scope"] === "sca");
  const points = [{ date: "2026-01-04T00:00:00Z" }, { date: "2026-01-31T00:00:00Z" }];
  const keyOf = groupKeyOf("repo");

  it("the mixed and sca-only answers genuinely differ, so the checks below are not vacuous", () => {
    // Unscoped: 4 scan points, 4 rows. sca-only: 2 scan points, 2 rows.
    expect(trendFromFrames(scans, base).length).toBe(4);
    expect(trendFromFrames(scaScans, scaBase).length).toBe(2);
    // As of Jan 5 the mixed register has 2 open (S2, X1 — S1 resolved Jan 4, X2 Dec 5)
    // against sca's 1 (S2).
    expect(trendFromFrames(scans, base)[2]).toMatchObject({ date: "2026-01-05T00:00:00Z", open: 2 });
    expect(trendFromFrames(scaScans, scaBase)[1]).toMatchObject({ date: "2026-01-05T00:00:00Z", open: 1 });
  });

  it("trendFromFrames scoped == the same computation over the sca-only subset", () => {
    expect(trendFromFrames(scans, base, null, { scope: "sca" }))
      .toEqual(trendFromFrames(scaScans, scaBase));
  });

  it("openBySeverityTrend / openByGroupTrend / the two MTTR group trends agree", () => {
    expect(openBySeverityTrend(scans, base, null, { scope: "sca" }))
      .toEqual(openBySeverityTrend(scaScans, scaBase));
    expect(openByGroupTrend(scans, base, keyOf, ["web", "db"], { scope: "sca" }))
      .toEqual(openByGroupTrend(scaScans, scaBase, keyOf, ["web", "db"]));
    expect(medianMttrByGroupTrend(scans, base, keyOf, ["web", "db"], { scope: "sca" }))
      .toEqual(medianMttrByGroupTrend(scaScans, scaBase, keyOf, ["web", "db"]));
    expect(kmMedianByGroupTrend(scans, base, keyOf, ["web", "db"], { scope: "sca" }))
      .toEqual(kmMedianByGroupTrend(scaScans, scaBase, keyOf, ["web", "db"]));
  });

  it("trendFromBase agrees with and without backfill", () => {
    expect(trendFromBase(scans, base, null, { scope: "sca" }))
      .toEqual(trendFromBase(scaScans, scaBase));
    expect(trendFromBase(scans, base, null, { backfill: true, scope: "sca" }))
      .toEqual(trendFromBase(scaScans, scaBase, null, { backfill: true }));
    // And backfill actually did something here — S1 is first seen 2025-12-20, 12 days before
    // the first sca scan (Dec 20 .. Dec 31 = 12 synthetic midnights + Jan 1..Jan 5 real).
    const withBackfill = trendFromBase(scans, base, null, { backfill: true, scope: "sca" });
    expect(withBackfill.filter((p) => p.reconstructed).length).toBe(12);
    expect(withBackfill[0].date).toBe("2025-12-20T00:00:00Z");
  });

  it("the point-decorators scope their ROWS (the point dates come from the caller)", () => {
    expect(withKmMedian(points, base, null, { scope: "sca" }))
      .toEqual(withKmMedian(points, scaBase));
    expect(withOpenPastSla(points, base, null, "first_seen", { scope: "sca" }))
      .toEqual(withOpenPastSla(points, scaBase));
    expect(withSlaBurn(points, base, null, { scope: "sca" })).toEqual(withSlaBurn(points, scaBase));
    expect(cohortSlaAttainment(points, base, null, { scope: "sca" }))
      .toEqual(cohortSlaAttainment(points, scaBase));
    expect(withCoverageEfficiency(points, base, RULE, null, { scope: "sca" }))
      .toEqual(withCoverageEfficiency(points, scaBase, RULE));
    const d = Date.parse("2026-01-31T00:00:00Z");
    expect(kmMedianAsOf(base, null, d, { scope: "sca" })).toBe(kmMedianAsOf(scaBase, null, d));
  });

  it("and the decorators' scoped answers differ from the unscoped ones", () => {
    // open_past_sla as of Jan 31. Mixed: S2 (HIGH, target 14, age 37d) and X1 (LOW, target
    // 90, age 152d) are both open past target -> 2. sca-only: S2 alone -> 1.
    expect(withOpenPastSla(points, base)[1].open_past_sla).toBe(2);
    expect(withOpenPastSla(points, scaBase)[1].open_past_sla).toBe(1);
    // Cohort attainment as of Jan 31. Every deadline has passed, so all four rows are in the
    // mixed cohort: S1 resolved Jan 4 after its Dec 27 deadline (miss), S2 open past Jan 8
    // (miss), X1 open past Nov 30 (miss), X2 resolved Dec 5 before its Dec 9 deadline (hit)
    // -> 1/4 = 25.0. sca-only: 0 of 2 -> 0.0.
    expect(cohortSlaAttainment(points, base)[1].sla_attainment_pct).toBe(25);
    expect(cohortSlaAttainment(points, scaBase)[1].sla_attainment_pct).toBe(0);
  });

  it("an unknown scope yields an empty series rather than the whole register", () => {
    expect(trendFromFrames(scans, base, null, { scope: "sast" })).toEqual([]);
    expect(openBySeverityTrend(scans, base, null, { scope: "sast" })).toEqual([]);
    expect(trendFromBase(scans, base, null, { backfill: true, scope: "sast" })).toEqual([]);
  });

  it("omitting the scope is byte-identical to today (parity lock)", () => {
    expect(trendFromFrames(scans, base, null, {})).toEqual(trendFromFrames(scans, base));
    expect(withKmMedian(points, base, null, {})).toEqual(withKmMedian(points, base));
    expect(withSlaBurn(points, base, null, {})).toEqual(withSlaBurn(points, base));
  });

  describe("perScopeSeries / trendByScope", () => {
    it("builds each scope's series from one pass, equal to the per-scope filtered call", () => {
      const byScope = trendByScope(scans, base);
      for (const scope of SCOPES) {
        expect(byScope[scope], scope).toEqual(trendFromBase(scans, base, null, { scope }));
      }
      // sast has no rows here, so its series is empty — an explicit answer, not a missing key.
      expect(Object.keys(byScope).sort()).toEqual([...SCOPES].sort());
      expect(byScope.sast).toEqual([]);
      expect(byScope.sca.length).toBe(2);
      expect(byScope.secrets.length).toBe(2);
    });

    it("agrees with the filtered call under backfill too (synthetic rows, both paths)", () => {
      const byScope = trendByScope(scans, base, null, { backfill: true });
      for (const scope of SCOPES) {
        expect(byScope[scope], scope)
          .toEqual(trendFromBase(scans, base, null, { backfill: true, scope }));
      }
      expect(byScope.sca.filter((p) => p.reconstructed).length).toBe(12);
    });

    it("hands `compute` the already-partitioned scans and rows", () => {
      const seen: Record<string, [number, number]> = {};
      perScopeSeries(scans, base, (s, b, scope) => {
        seen[scope] = [s.length, b.length];
        return null;
      });
      expect(seen).toEqual({ sca: [2, 2], sast: [0, 0], secrets: [2, 2] });
    });

    it("drops rows carrying a scope outside SCOPES — corrupt data, not a fourth register", () => {
      const seen: Record<string, number> = {};
      perScopeSeries(
        [...scans, { ts: "2026-01-09T00:00:00Z", scope: "iac" }],
        [...base, { scope: "iac", severity: "HIGH", first_seen: "2026-01-01T00:00:00Z" }],
        (s, b, scope) => {
          seen[scope] = s.length + b.length;
          return null;
        },
      );
      expect(seen).toEqual({ sca: 4, sast: 0, secrets: 4 });
    });
  });
});
